for k in range(100):
 e=np.array([1.95,1.65])-d.xpos[rb][:2];a=np.zeros(11);a[:2]=np.clip(e,-.1,.1);s.step(a)
 if np.linalg.norm(e)<.015:break
# calculate hover q target using DLS standard initial seed, then goal hardcode
qinit=d.qpos[qa].copy();d.qpos[96]=-1.5;mujoco.mj_forward(m,d)
def solve(t):
 for i in range(500):
  e=t-(d.xpos[l]+d.xpos[r])/2
  if np.linalg.norm(e)<.002:break
  j1=np.zeros((3,m.nv));r1=np.zeros((3,m.nv));j2=np.zeros((3,m.nv));r2=np.zeros((3,m.nv));mujoco.mj_jacBody(m,d,j1,r1,l);mujoco.mj_jacBody(m,d,j2,r2,r);J=((j1+j2)/2)[:,adr];dq=J.T@np.linalg.solve(J@J.T+.003*np.eye(3),e);d.qpos[qa]+=np.clip(dq,-.06,.06);mujoco.mj_forward(m,d)
 return d.qpos[qa].copy()
qh=solve(np.array([1.558,.75,.45]));qg=np.array([.456,1.509,3.325,-1.419,.076,.993,-1.5]);
print('hover',qh,'goal err');d.qpos[qa]=qg;mujoco.mj_forward(m,d);print(np.linalg.norm(np.array([1.558,.89,.30])-(d.xpos[l]+d.xpos[r])/2),'pads',d.xpos[l],d.xpos[r])
for f in np.linspace(0,1,21):
 d.qpos[qa]=(1-f)*qh+f*qg;mujoco.mj_forward(m,d);cs=[]
 for j in range(d.ncon):
  c=d.contact[j];n1=m.body(m.geom_bodyid[c.geom1]).name;n2=m.body(m.geom_bodyid[c.geom2]).name
  if 'wiper' in n1+n2 and 'scene' not in n1+n2:cs.append((n1,n2,round(c.dist,4)))
